using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Looks up a configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var store = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["app:name"] = "ConfigMcpServer",
            ["app:version"] = "1.0.0",
            ["app:environment"] = "Production",
            ["feature:darkMode"] = "true",
            ["feature:maxRetries"] = "3"
        };

        return store.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", store.Keys)}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAllSettings()
    {
        var settings = new
        {
            App = new { Name = "ConfigMcpServer", Version = "1.0.0", Environment = "Production" },
            Features = new { DarkMode = true, MaxRetries = 3 },
            Limits = new { MaxRequestsPerMinute = 100, TimeoutSeconds = 30 }
        };

        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/features",
        Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns current feature flag values.")]
    public static string GetFeatureFlags()
    {
        var flags = new { DarkMode = true, MaxRetries = 3, BetaEnabled = false };
        return JsonSerializer.Serialize(flags, new JsonSerializerOptions { WriteIndented = true });
    }
}

